import itertools
G=[[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]
coords={(r,c) for r,row in enumerate(G) for c,v in enumerate(row) if v}
print(len(coords))
cands=[]
for r in range(len(G)-1):
 for c in range(6):
  sq={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  inter=sq&coords
  if len(inter) in (3,4): cands.append((r,c,inter, 'square' if len(inter)==4 else 'L'))
print([(r,c,len(s),sorted(s)) for r,c,s,t in cands])
sols=[]
def rec(rem,sel):
 if not rem:
  sols.append(sel); return
 x=min(rem)
 for cand in cands:
  if x in cand[2] and cand[2]<=rem:
   rec(rem-cand[2], sel+[cand])
rec(coords,[])
print('sols',len(sols))
for s in sols[:20]: print([(x[0],x[1],x[3], sorted(x[2])) for x in s])
